+// adjustChunkLimit picks the next chunk's Limit so each chunk lands near
+// the target size. Always returning at least one is important because zero
+// means an unlimited range request.
+func adjustChunkLimit(lastLimit int64, lastSize, targetSize int) int64 {
+	switch {
+	case targetSize > 0 && lastSize < targetSize/2:
+		if lastLimit > math.MaxInt64/2 {
+			lastLimit = math.MaxInt64
+		} else {
+			lastLimit *= 2
+		}
+	case targetSize <= 0 || (lastSize > targetSize && lastSize-targetSize > targetSize):
+		lastLimit /= 2
+	}
+	if lastLimit < 1 {
+		lastLimit = 1
+	}
+	return lastLimit
